import{_ as e,o as a,c as o,a3 as r}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Operator notification mailbox — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Operator notification mailbox — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/ops-notification-email-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Operator notification mailbox — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/ops-notification-email-production-readiness"}]]},"headers":[],"relativePath":"deployment/ops-notification-email-production-readiness.md","filePath":"deployment/ops-notification-email-production-readiness.md","lastUpdated":1792536698000}'),n={name:"deployment/ops-notification-email-production-readiness.md"};function s(i,t,d,l,c,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="operator-notification-mailbox-—-production-readiness-audit" tabindex="-1">Operator notification mailbox — Production Readiness Audit <a class="header-anchor" href="#operator-notification-mailbox-—-production-readiness-audit" aria-label="Permalink to &quot;Operator notification mailbox — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-20</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> — feature Pest <strong>9/9</strong>; headed Playwright <strong>1/1</strong> (plus central login setup)</td></tr><tr><td><strong>Scope</strong></td><td>Central setting <code>ops_notification_email</code> emails operators for new feedback, beta applications, and self-service workspace signups</td></tr><tr><td><strong>Catalog</strong></td><td>No bump</td></tr><tr><td><strong>Companion</strong></td><td><a href="/user-guide/central-settings">Central settings user guide</a> · <a href="/developer-guide/central-settings">Central settings developer guide</a> · <a href="/developer-guide/central-feedback-system">Central feedback</a> · <a href="/api/central-v1">Central API</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Operators choose one mailbox under <strong>Central Settings → Mail</strong>. When it is set, EloSync queues mail after a workspace submits feedback (any type; critical bugs use a critical subject), after a public beta application is stored, and after a self-service workspace signup commits. A blank address sends none of those. Superadmin users are not recipients. Workspaces created by a Central admin do not send this mail. Public <code>support_email</code> is unchanged.</p><p><strong>Go / No-Go:</strong> <strong>Go.</strong> Deploy Backend and Frontend together. No migrate. Set the mailbox after deploy or these three alerts stay off.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong> — existing Central settings form and notification mail</td></tr><tr><td>Setting stored and omitted from public bootstrap</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Feedback, beta application, and self-service signup mail the mailbox</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Blank mailbox and admin-created workspaces send nothing</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Superadmin user is not a recipient</td><td><strong>Pass</strong> (Pest)</td></tr><tr><td>Invalid email shows field error and toast; valid save, clear, and restore</td><td><strong>Pass</strong> (headed Playwright, one login)</td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>Setting update still requires <code>system-settings.update</code></td><td>Pass</td></tr><tr><td>Address is not included in the public bootstrap payload</td><td>Pass</td></tr><tr><td>Mail is on-demand to the configured address, not fanned out to Central users</td><td>Pass</td></tr><tr><td>No new permission</td><td>Pass</td></tr></tbody></table><hr><h2 id="findings-disposition" tabindex="-1">Findings disposition <a class="header-anchor" href="#findings-disposition" aria-label="Permalink to &quot;Findings disposition&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>F1</strong></td><td>Medium</td><td>Central Playwright setup launched missing bundled Chromium even when <code>E2E_BROWSER_CHANNEL=chrome</code></td><td><strong>Fixed</strong> — setup and chromium projects use the same channel as tenant</td></tr><tr><td><strong>F2</strong></td><td>Low</td><td>Shared e2e admin had two-factor enabled, so API login returned no token</td><td><strong>Fixed for this run</strong> — <code>php scripts/reset-e2e-central-admin.php</code> (existing e2e helper). Re-run it if a two-factor spec leaves 2FA on</td></tr><tr><td><strong>I1</strong></td><td>Info</td><td>Invalid operator email shows both the field error and a toast</td><td><strong>Accepted</strong> — same pattern as other Central settings validation</td></tr></tbody></table><hr><h2 id="headed-browser-coverage" tabindex="-1">Headed browser coverage <a class="header-anchor" href="#headed-browser-coverage" aria-label="Permalink to &quot;Headed browser coverage&quot;">​</a></h2><p><code>npm run test:e2e:ops-notification:headed</code> on 2026-10-20. Result: <strong>2 passed</strong> (central login setup + one serial session).</p><p>One central login, one page session:</p><ol><li>Open <strong>Settings → Mail</strong> and confirm the operator email field and helper text</li><li>Enter <code>not-an-email</code>, save → field error <strong>Enter a valid operator email</strong> and the same toast; settings are not saved</li><li>Enter a valid address, save, reload → value persists</li><li>Clear the field, save, reload → blank</li><li>Restore the address that was there before the test</li></ol><hr><h2 id="upgrade" tabindex="-1">Upgrade <a class="header-anchor" href="#upgrade" aria-label="Permalink to &quot;Upgrade&quot;">​</a></h2><ol><li>Deploy Backend (no migrate). The key is created when settings are seeded or when an admin saves it.</li><li>Deploy Frontend SPA and hard-refresh.</li><li>Open <strong>Settings → Mail</strong> and set <strong>Operator notification email</strong>, or leave it blank.</li><li>Smoke: save an invalid address (error, no success toast), then a valid address, reload, and confirm it stuck.</li></ol>',21)])])}const g=e(n,[["render",s]]);export{m as __pageData,g as default};
